\title{Oddomorphisms of Finite Graphs:\\ An Algebraic Backbone for the Split-Off Minor Correspondence}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\maketitle

\begin{abstract}
We study \emph{oddomorphisms} between finite graphs --- functions on vertex sets
whose associated $0/1$ function matrices intertwine the adjacency matrices of the
two graphs over the two-element field $\GF(2)$. Equivalently, a function
$\varphi\colon \V(F)\to \V(G)$ is an oddomorphism precisely when, for every vertex
$u$ of $F$ and every vertex $a$ of $G$, the number of neighbours of $u$ mapped by
$\varphi$ to $a$ is odd if and only if $\varphi(u)$ is adjacent to $a$ in $G$. This
local parity condition is a ``modulo two'' relaxation of the notion of a graph
homomorphism. We establish the categorical and order-theoretic foundations of the
relation: the function matrix is contravariantly functorial, the identity is an
oddomorphism, and oddomorphisms compose, so that the existence of an oddomorphism
defines a preorder on graphs over a fixed vertex set. Every graph isomorphism is an
oddomorphism, and self-oddomorphisms form a submonoid of the endofunction monoid.
We give a transparent local-parity characterization and exhibit an explicit
non-injective, surjective oddomorphism from the two-edge graph $2K_2$ onto the
single-edge graph $K_2$, while proving the constant map is not an oddomorphism.
These results form the algebraic backbone of the conjectured equivalence between
the existence of an oddomorphism $F\to G$ and $G$ being a split-off minor of $F$,
whose forward direction is known and whose converse remains open.
\end{abstract}

\section{Introduction}

The comparison of finite graphs by structure-preserving maps is a cornerstone of
combinatorics, spanning the extremes of \emph{isomorphism} (an exact, invertible
relabelling) and \emph{homomorphism} (an edge-preserving map allowing collapse).
Between these lies a landscape of relations obtained by relaxing
``edge-preserving.'' We study a relaxation that replaces edge-preservation with a
\emph{parity} condition over the field $\GF(2)$.

An \emph{oddomorphism} from a finite graph $F$ to a finite graph $G$ is a vertex map
whose local neighbourhood behaviour is governed by odd-versus-even counting rather
than set inclusion. The notion arises in the study of homomorphism-count
indistinguishability and quantum isomorphism of graphs, where invariants defined
modulo two separate pairs of graphs that classical counting cannot; the underlying
algebra of graph operations, including the split-off operation central to the
motivating conjecture, traces back to foundational work on graph transformations.
Our purpose is to lay down rigorously the algebraic and order-theoretic
infrastructure on the oddomorphism side.

\section{Preliminaries and notation}

All graphs are finite and simple: a graph $F$ is a finite vertex set $\V(F)$ with an
irreflexive symmetric adjacency relation $u \sim_F v$. We work over the two-element
field $\GF(2)=\{0,1\}$ with $1+1=0$.

The \emph{adjacency matrix} $A_F \in \GF(2)^{\V(F)\times \V(F)}$ has
$(A_F)_{u,v}=1$ iff $u\sim_F v$; it is symmetric with zero diagonal. For a function
$\varphi\colon\alpha\to\beta$ between finite sets, its \emph{function matrix}
$M_\varphi\in\GF(2)^{\alpha\times\beta}$ has $(M_\varphi)_{u,a}=1$ iff $\varphi(u)=a$
and $0$ otherwise; each row contains exactly one $1$, and $M_{\mathrm{id}}=I$. All
matrix products and entry sums are taken modulo two.

\section{Oddomorphisms}

\begin{definition}[Oddomorphism]
Let $F,G$ be finite graphs. A function $\varphi\colon\V(F)\to\V(G)$ is an
\emph{oddomorphism} from $F$ to $G$ if its function matrix intertwines the adjacency
matrices over $\GF(2)$:
\begin{equation}\label{eq:intertwine}
A_F\, M_\varphi = M_\varphi\, A_G.
\end{equation}
We write $F\rightsquigarrow G$ if such an oddomorphism exists.
\end{definition}

\begin{lemma}[Left product]\label{lem:left}
For all $u\in\V(F)$, $a\in\V(G)$,
\[
(A_F M_\varphi)_{u,a} = \sum_{v\in\V(F)} [\, u\sim_F v \wedge \varphi(v)=a \,]
\pmod 2,
\]
where $[\cdot]$ is $1$ when the condition holds and $0$ otherwise.
\end{lemma}

\begin{proof}
Expand $(A_F M_\varphi)_{u,a}=\sum_v (A_F)_{u,v}(M_\varphi)_{v,a}$. Here
$(A_F)_{u,v}=1$ iff $u\sim_F v$ and $(M_\varphi)_{v,a}=1$ iff $\varphi(v)=a$; the
product is $1$ iff both hold.
\end{proof}

\begin{lemma}[Right product]\label{lem:right}
For all $u\in\V(F)$, $a\in\V(G)$, $\ (M_\varphi A_G)_{u,a} = [\,\varphi(u)\sim_G a\,]$.
\end{lemma}

\begin{proof}
$(M_\varphi A_G)_{u,a}=\sum_b (M_\varphi)_{u,b}(A_G)_{b,a}$ collapses to the single
term $b=\varphi(u)$, giving $(A_G)_{\varphi(u),a}=[\varphi(u)\sim_G a]$.
\end{proof}

\begin{theorem}[Local parity characterization]\label{thm:parity}
A function $\varphi\colon\V(F)\to\V(G)$ is an oddomorphism if and only if, for all
$u\in\V(F)$ and $a\in\V(G)$,
\[
\#\{\, v : u\sim_F v \text{ and } \varphi(v)=a\,\} \equiv [\,\varphi(u)\sim_G a\,]
\pmod 2.
\]
Equivalently, the number of neighbours of $u$ sent by $\varphi$ to $a$ is odd iff
$\varphi(u)$ is adjacent to $a$ in $G$.
\end{theorem}

\begin{proof}
Equation \eqref{eq:intertwine} holds iff it holds entrywise. By
Lemmas~\ref{lem:left} and \ref{lem:right} the $(u,a)$ entries of the two sides are
exactly the two sides of the parity congruence.
\end{proof}

\section{Functoriality and the preorder structure}

\begin{theorem}[Contravariant functoriality]\label{thm:funct}
For $\varphi\colon\alpha\to\beta$ and $\psi\colon\beta\to\gamma$ between finite sets,
$M_\varphi\, M_\psi = M_{\psi\circ\varphi}$.
\end{theorem}

\begin{proof}
Fix $u,c$. In $(M_\varphi M_\psi)_{u,c}=\sum_b (M_\varphi)_{u,b}(M_\psi)_{b,c}$ every
term with $b\neq\varphi(u)$ vanishes, leaving $(M_\psi)_{\varphi(u),c}$, which is $1$
iff $\psi(\varphi(u))=c$, i.e. $(M_{\psi\circ\varphi})_{u,c}$.
\end{proof}

\begin{theorem}[Reflexivity]\label{thm:refl}
For every finite graph $F$, the identity is an oddomorphism $F\to F$.
\end{theorem}

\begin{proof}
$M_{\mathrm{id}}=I$ and $A_F I = A_F = I A_F$.
\end{proof}

\begin{theorem}[Transitivity]\label{thm:trans}
If $\varphi$ is an oddomorphism $F\to G$ and $\psi$ is an oddomorphism $G\to H$, then
$\psi\circ\varphi$ is an oddomorphism $F\to H$.
\end{theorem}

\begin{proof}
Using Theorem~\ref{thm:funct}, the hypotheses $A_F M_\varphi = M_\varphi A_G$,
$A_G M_\psi = M_\psi A_H$, and associativity:
\[
A_F M_{\psi\circ\varphi} = A_F(M_\varphi M_\psi) = (A_F M_\varphi)M_\psi
= (M_\varphi A_G)M_\psi = M_\varphi(A_G M_\psi)
\]
\[
= M_\varphi(M_\psi A_H) = (M_\varphi M_\psi)A_H = M_{\psi\circ\varphi}A_H. \qedhere
\]
\end{proof}

\begin{theorem}[Preorder]\label{thm:preorder}
Fix a finite vertex set $V$. The relation $F\rightsquigarrow G$ is a preorder on the
simple graphs with vertex set $V$: reflexive (Theorem~\ref{thm:refl}) and transitive
(Theorem~\ref{thm:trans}).
\end{theorem}

\section{Isomorphisms and the self-oddomorphism monoid}

\begin{theorem}[Isomorphisms are oddomorphisms]\label{thm:iso}
Every graph isomorphism $\varphi\colon F\to G$ is an oddomorphism. Hence isomorphic
graphs are oddomorphism-equivalent, and every automorphism of $F$ is a
self-oddomorphism.
\end{theorem}

\begin{proof}[Proof sketch]
For an isomorphism, the parity condition of Theorem~\ref{thm:parity} holds with all
counts equal to $0$ or $1$: for $a=\varphi(w)$ the neighbours of $u$ mapping to $a$
are $\{w\}$ or $\varnothing$ according as $u\sim_F w$, and $\varphi(u)\sim_G
\varphi(w)$ iff $u\sim_F w$; if $a$ is not in the image the case is vacuous by
surjectivity. In all cases the parities agree.
\end{proof}

\begin{theorem}[Self-oddomorphism submonoid]\label{thm:monoid}
For a fixed finite graph $F$, the self-oddomorphisms $F\to F$ form a submonoid of the
monoid of endofunctions of $\V(F)$ under composition, containing $\Aut(F)$.
\end{theorem}

\begin{proof}
The identity is a self-oddomorphism (Theorem~\ref{thm:refl}) and the set is closed
under composition (Theorem~\ref{thm:trans}); $\Aut(F)$ is contained by
Theorem~\ref{thm:iso}.
\end{proof}

\section{A concrete non-injective oddomorphism}

Let $F=2K_2$ on $\{0,1,2,3\}$ with edges $\{0,1\}$ and $\{2,3\}$, and $G=K_2$ the
single edge on $\{0,1\}$. Define the folding map
\[
\varphi(0)=0,\quad \varphi(1)=1,\quad \varphi(2)=0,\quad \varphi(3)=1.
\]

\begin{theorem}\label{thm:example}
The folding map $\varphi$ is a surjective, non-injective oddomorphism $2K_2\to K_2$.
The constant map $\{0,1,2,3\}\to\{0\}$ is not an oddomorphism.
\end{theorem}

\begin{proof}[Proof sketch]
Check Theorem~\ref{thm:parity} at each vertex. For $u=0$, the unique neighbour $1$
has $\varphi(1)=1$, so the count of neighbours mapped to $0$ is even and to $1$ is
odd; in $G$, $\varphi(0)=0$ is adjacent to $1$ but not $0$, matching both. The
remaining vertices are symmetric. Surjectivity is clear; non-injectivity holds since
$\varphi(0)=\varphi(2)$. For the constant map $c$: at $u=0$ the neighbour $1$ has
$c(1)=0$, giving an odd count of neighbours mapped to $0$ and demanding $0\sim_G 0$,
which fails since $K_2$ has no loop; so $c$ is not an oddomorphism.
\end{proof}

The folding exhibits $K_2$ as a minor of $2K_2$ (delete one edge and identify its
endpoints with the other's); that it is an oddomorphism while the total collapse is
not is a microcosm of the general correspondence.

\section{The split-off minor correspondence}

\begin{conjecture}[Oddomorphism / split-off minor equivalence]\label{conj:main}
For all finite graphs $F,G$, there exists an oddomorphism $F\to G$ if and only if $G$
is a split-off minor of $F$.
\end{conjecture}

A split-off minor is obtained from $F$ by a finite sequence of vertex splitting-off
operations together with deletions. The forward direction --- a split-off minor of
$F$ admits an oddomorphism from $F$ --- is known: each split-off step induces an
oddomorphism and Theorem~\ref{thm:trans} chains them into one. The converse remains
open. The preorder of Theorem~\ref{thm:preorder} is the order-theoretic shadow the
correspondence asserts coincides with the split-off-minor order, and
Theorem~\ref{thm:example} makes a base case fully explicit.

\section{Discussion and future work}

We isolate the following directions.
\begin{enumerate}
  \item Rigorously define the split-off and split-off-minor operations and prove each step
  induces an oddomorphism; compose via Theorem~\ref{thm:trans} for the forward
  direction of Conjecture~\ref{conj:main}.
  \item Develop the kernel/rank theory of $A_F M = M A_G$ over $\GF(2)$ to attack the
  converse.
  \item Relate the count of oddomorphisms modulo two to homomorphism counts modulo
  two and to quantum-isomorphism invariants.
  \item Determine when $F\rightsquigarrow G$ and $G\rightsquigarrow F$ force
  $F\cong G$, refining the preorder to a partial order.
  \item Characterize graphs whose self-oddomorphism monoid strictly exceeds
  $\Aut(F)$.
\end{enumerate}

\section{Conclusion}

Oddomorphisms recast graph comparison through $\GF(2)$ parity, and the recasting is
well-behaved: the intertwining condition is functorial, reflexive, and transitive,
giving a preorder refining isomorphism; isomorphisms are oddomorphisms;
self-oddomorphisms form a monoid; and strictly non-injective oddomorphisms witness
genuine minors while a guardrail example shows the notion is genuinely constrained.
These constitute the foundation on which the conjectured equivalence with split-off
minors rests.

