from __future__ import annotations
from typing import List, Sequence, Tuple

Matrix = List[List[int]]
Edge = Tuple[int, int]


def mat_mul_gf2(a: Matrix, b: Matrix) -> Matrix:
    r, k, c = len(a), len(b), len(b[0])
    out = [[0] * c for _ in range(r)]
    for i in range(r):
        for t in range(k):
            if a[i][t] & 1:
                for j in range(c):
                    out[i][j] ^= b[t][j] & 1
    return out


def adjacency(n: int, edges: Sequence[Edge]) -> Matrix:
    a = [[0] * n for _ in range(n)]
    for u, v in edges:
        a[u][v] = a[v][u] = 1
    return a


def function_matrix(phi: Sequence[int], m: int) -> Matrix:
    mat = [[0] * m for _ in range(len(phi))]
    for u, im in enumerate(phi):
        mat[u][im] = 1
    return mat


def is_oddomorphism(a_f: Matrix, a_g: Matrix, phi: Sequence[int]) -> bool:
    mp = function_matrix(phi, len(a_g))
    return mat_mul_gf2(a_f, mp) == mat_mul_gf2(mp, a_g)


if __name__ == "__main__":
    a_f = adjacency(4, [(0, 1), (2, 3)])   # 2K2
    a_g = adjacency(2, [(0, 1)])           # K2
    phi = [0, 1, 0, 1]
    print("folding map oddomorphism? ", is_oddomorphism(a_f, a_g, phi))
    print("surjective?", set(phi) == {0, 1}, " injective?", len(set(phi)) == 4)
    print("constant map oddomorphism?", is_oddomorphism(a_f, a_g, [0, 0, 0, 0]))

