"""Bar chart: number of oddomorphisms vs automorphisms for a few small graphs."""
from itertools import permutations, product
import matplotlib.pyplot as plt


def adj(n, edges):
    a = [[0] * n for _ in range(n)]
    for u, v in edges:
        a[u][v] = a[v][u] = 1
    return a


def mul(a, b):
    r, k, c = len(a), len(b), len(b[0])
    o = [[0] * c for _ in range(r)]
    for i in range(r):
        for t in range(k):
            if a[i][t]:
                for j in range(c):
                    o[i][j] ^= b[t][j] & 1
    return o


def fmat(phi, m):
    M = [[0] * m for _ in range(len(phi))]
    for u, im in enumerate(phi):
        M[u][im] = 1
    return M


def count_oddo(n, e):
    A = adj(n, e)
    return sum(1 for p in product(range(n), repeat=n)
               if mul(A, fmat(p, n)) == mul(fmat(p, n), A))


def count_aut(n, e):
    A = adj(n, e)
    def perm_ok(p):
        return all(A[i][j] == A[p[i]][p[j]] for i in range(n) for j in range(n))
    return sum(1 for p in permutations(range(n)) if perm_ok(p))


graphs = {
    "P3": (3, [(0, 1), (1, 2)]),
    "K3": (3, [(0, 1), (1, 2), (0, 2)]),
    "P4": (4, [(0, 1), (1, 2), (2, 3)]),
    "C4": (4, [(0, 1), (1, 2), (2, 3), (3, 0)]),
}
names = list(graphs)
oddo = [count_oddo(*graphs[g]) for g in names]
aut = [count_aut(*graphs[g]) for g in names]

x = range(len(names))
plt.bar([i - 0.2 for i in x], oddo, width=0.4, label="self-oddomorphisms")
plt.bar([i + 0.2 for i in x], aut, width=0.4, label="automorphisms")
plt.xticks(list(x), names)
plt.ylabel("count")
plt.title("Self-oddomorphism monoid vs automorphism group")
plt.legend()
plt.tight_layout()
plt.savefig("oddo_vs_aut.png", dpi=150)
print("saved oddo_vs_aut.png")
